window.ScripturaLexicons.BDAG_PART_0206 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0206-01\" data-source=\"BDAG\" data-search=\"κολαβρίζω verbo zombar; ridicularizar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κολαβρίζω</td><td>verbo</td><td>zombar; ridicularizar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0206-02\" data-source=\"BDAG\" data-search=\"κολάζω verbo castigar; punir; penalizar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κολάζω</td><td>verbo</td><td>castigar; punir; penalizar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0206-03\" data-source=\"BDAG\" data-search=\"κολακεία, ας, ἡ substantivo feminino lisonja; adulação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κολακεία, ας, ἡ</td><td>substantivo feminino</td><td>lisonja; adulação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0206-04\" data-source=\"BDAG\" data-search=\"κολακεύω verbo adular; lisonjear; tratar com brandura BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κολακεύω</td><td>verbo</td><td>adular; lisonjear; tratar com brandura</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0206-05\" data-source=\"BDAG\" data-search=\"κόλασις, εως, ἡ substantivo feminino castigo; punição; tormento; punição eterna BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κόλασις, εως, ἡ</td><td>substantivo feminino</td><td>castigo; punição; tormento; punição eterna</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0206-06\" data-source=\"BDAG\" data-search=\"Κολασσαεύς substantivo masculino; variante gráfica e remissão colossense; variante de Κολοσσαεύς BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κολασσαεύς</td><td>substantivo masculino; variante gráfica e remissão</td><td>colossense; variante de Κολοσσαεύς</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0206-07\" data-source=\"BDAG\" data-search=\"Κολασσαί nome próprio geográfico; remissão Colossos; veja Κολοσσαί BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κολασσαί</td><td>nome próprio geográfico; remissão</td><td>Colossos; veja Κολοσσαί</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0206-08\" data-source=\"BDAG\" data-search=\"κολαφίζω verbo esmurrar; espancar; maltratar; atormentar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κολαφίζω</td><td>verbo</td><td>esmurrar; espancar; maltratar; atormentar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0206-09\" data-source=\"BDAG\" data-search=\"κολλάω verbo colar; unir firmemente; aderir; associar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κολλάω</td><td>verbo</td><td>colar; unir firmemente; aderir; associar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0206-10\" data-source=\"BDAG\" data-search=\"κολλούριον, ου, τό substantivo neutro colírio; unguento para os olhos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κολλούριον, ου, τό</td><td>substantivo neutro</td><td>colírio; unguento para os olhos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0206-11\" data-source=\"BDAG\" data-search=\"κολλυβιστής, οῦ, ὁ substantivo masculino cambista; trocador de dinheiro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κολλυβιστής, οῦ, ὁ</td><td>substantivo masculino</td><td>cambista; trocador de dinheiro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0206-12\" data-source=\"BDAG\" data-search=\"κολλύριον remissão lexical veja κολλούριον BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κολλύριον</td><td>remissão lexical</td><td>veja κολλούριον</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0206-13\" data-source=\"BDAG\" data-search=\"κολοβός, όν adjetivo mutilado; incompleto; baixo; atarracado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κολοβός, όν</td><td>adjetivo</td><td>mutilado; incompleto; baixo; atarracado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0206-14\" data-source=\"BDAG\" data-search=\"κολοβόω verbo encurtar; reduzir; mutilar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κολοβόω</td><td>verbo</td><td>encurtar; reduzir; mutilar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0206-15\" data-source=\"BDAG\" data-search=\"Κολοσσαεύς, έως substantivo masculino; gentílico colossense; habitante de Colossos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κολοσσαεύς, έως</td><td>substantivo masculino; gentílico</td><td>colossense; habitante de Colossos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0206-16\" data-source=\"BDAG\" data-search=\"Κολοσσαί, ῶν, αἱ nome próprio geográfico feminino plural Colossos, cidade da Frígia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κολοσσαί, ῶν, αἱ</td><td>nome próprio geográfico feminino plural</td><td>Colossos, cidade da Frígia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0206-17\" data-source=\"BDAG\" data-search=\"κόλπος, ου, ὁ substantivo masculino seio; peito; colo; dobra de roupa; baía BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κόλπος, ου, ὁ</td><td>substantivo masculino</td><td>seio; peito; colo; dobra de roupa; baía</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0206-18\" data-source=\"BDAG\" data-search=\"κολυμβάω verbo mergulhar; nadar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κολυμβάω</td><td>verbo</td><td>mergulhar; nadar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0206-19\" data-source=\"BDAG\" data-search=\"κολυμβήθρα, ας, ἡ substantivo feminino piscina; tanque; reservatório para banho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κολυμβήθρα, ας, ἡ</td><td>substantivo feminino</td><td>piscina; tanque; reservatório para banho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0206-20\" data-source=\"BDAG\" data-search=\"κολωνία, ας, ἡ substantivo feminino colônia; cidade com privilégios políticos romanos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κολωνία, ας, ἡ</td><td>substantivo feminino</td><td>colônia; cidade com privilégios políticos romanos</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0206-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κολαβρίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κολαβρίζω</span>: 1º aoristo passivo <span class=\"greek\">ἐκολαβρίσθην</span> (Hesychius): zombar, ridicularizar (Suda), 1 Cl 39:9 (Job 5:4).—DELG s.v. <span class=\"greek\">κόλαβρο</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0206-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κολάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κολάζω</span>: futuro <span class=\"greek\">κολάσω</span>; 1º aoristo médio <span class=\"greek\">ἐκολασάμην</span>. Passiva: 1º futuro <span class=\"greek\">κολασθήσομαι</span>; aoristo, 3ª pessoa do plural, <span class=\"greek\">ἐκολάσθησαν</span>, LXX; infinitivo perfeito <span class=\"greek\">κεκολάσθαι</span> (veja os três verbetes seguintes): penalizar, punir (assim nos autores trágicos, Pla. e posteriores; também OGI 90, 28; PSI 446, 14; PRyl 62, 9). Na ativa, com <span class=\"greek\">τινά</span>, alguém, literalmente, a respeito do castigo dos escravos, Hs 9, 28, 8. Em linguagem figurada: causar dano a alguém, dos politeístas que castigam suas imagens de culto trancando-as, Dg 2:8. Num lugar apocalíptico de punição encontram-se <span class=\"greek\">οἱ</span> <span class=\"greek\">κολάζοντες</span> <span class=\"greek\">ἄγγελοι</span>, os anjos que punem, ApcPt 6:21b (Chariton 4, 2, 7 <span class=\"greek\">οἱ</span> <span class=\"greek\">κολάζοντες</span> = ‘guardas, policiais’; Sallust. 19 p. 34, 15 <span class=\"greek\">δαίμονες</span> <span class=\"greek\">κολάζοντες</span>).—Na voz média (Aristoph., Vesp. 405; Pla., Protag. 324c; 3 Macc 7:3; ApcEsdr 1:11 p. 25, 4 Tdf.; Just., A II, 2, 9; 11; 16), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:21</a>.—Predominantemente na passiva, quanto à punição de cristãos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:20</a>, variante de leitura; Dg 5:16; 6:9; 7:8; 10:7; MPol 2:4. Sobre o Juízo Final, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:9</a>. <span class=\"greek\">βασάνοις</span>, por meio de tormentos, 2 Cl 17:7 (sobre o dativo, compare Appian, Bell. Civ. 2, 90 §377 <span class=\"greek\">κ</span>. <span class=\"greek\">θανάτῳ</span>; Polyaenus 3, 9, 56; Lucian, Dial. Mort. 17, 2; Jos., Ant. 18, 314 <span class=\"greek\">κ</span>. <span class=\"greek\">πληγαῖς</span>.—Just., A II, 1, 2 <span class=\"greek\">ἐν</span> <span class=\"greek\">πυρί</span>). <span class=\"greek\">δισσῶς</span>, ser punido duplamente, Hs 9, 18, 2. Sobre o inferno: <span class=\"greek\">οἱ</span> <span class=\"greek\">κολαζόμενοι</span> <span class=\"greek\">ἐκεῖ</span>, os que são punidos ali, ApcPt 6:21a. (Sobre a punição divina: TestAsh 6:2; ApcEsdr 1:11; Just., D. 88, 5; Diod S 16, 32, 1; Epict. 3, 11, 3; Dio Chrys. 59 [76], 5; Aesop, Fab. 77 P. = 127 H. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">κολάζονται</span>, são punidos pelos deuses; frequentemente em inscrições em FSteinleitner, D. Beicht 1913, p. 10ff; LRobert, Nouvelles Inscriptions de Sardes ’64, 24ff; LXX; Jos., Bell. 2, 163; compare Theoph. Ant., 2, 36 [p. 196, 24]). A restrição que Aristóteles faz do termo <span class=\"greek\">κόλασις</span> à ação disciplinar, Rhet. 1, 10, 17, não se reflete no uso geral.—DELG s.v. <span class=\"greek\">κόλος</span> 3. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0206-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κολακεία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κολακεία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (veja o verbete seguinte; editores também registram a terminação -<span class=\"greek\">ία</span>; desde Pla.; Philod. [<span class=\"greek\">Περὶ</span> <span class=\"greek\">κολακείας</span>: RhM n.F. 56, 1901, 623]; SIG 889, 30 <span class=\"greek\">κολακείᾳ</span>; PLond V, 1727, 24; TestAbr A [-<span class=\"greek\">ία</span>]; Philo; Jos., Bell. 4, 231, Ant. 16, 301. Sobre a grafia, veja B-D-F §23; W-S. §5, 13c; Mlt-H. 339): lisonja, adulação; <span class=\"greek\">λόγος</span> <span class=\"greek\">κολακείας</span>, palavras lisonjeiras, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:5</a>.—JLofberg, The Sycophant-Parasite: ClPh 15, 1920, 71.—DELG s.v. <span class=\"greek\">κόλαξ</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0206-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κολακεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κολακεύω</span>: futuro <span class=\"greek\">κολακεύσω</span>; 1º aoristo <span class=\"greek\">ἐκολάκευσα</span> (veja o verbete precedente; desde Aristoph., Pla.; PSI 586, 4; LXX; TestJos 4:1; Philo; Jos., Bell. 2, 213, Vi. 367; Just., A I, 2, 3; Tat.). Em geral, ‘adular’. Em nossa literatura, apenas em Ignácio, e aí com sentido favorável, algo como atrair, tratar com gentileza, com acusativo (Philo, Spec. Leg. 1, 60): <span class=\"greek\">τὰ</span> <span class=\"greek\">θηρία</span>, as feras (Vi. Aesopi W c. 49 <span class=\"greek\">κολακεύω</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κύνα</span> = afagar o cão), IRo 4:2; 5:2. <span class=\"greek\">τὰ</span> <span class=\"greek\">φαινόμενά</span> <span class=\"greek\">σου</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">πρόσωπον</span>, aquilo que aparece diante de teu rosto, IPol 2:2. Sobre IRo 6:2, veja Bihlmeyer, margem.—DELG s.v. <span class=\"greek\">κόλαξ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0206-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κόλασις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κόλασις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (veja os três verbetes precedentes; ‘punição, castigo’, assim desde Hippocr.; Diod S 1, 77, 9; 4, 44, 3; Aelian, VH 7, 15; SIG2 680, 13; LXX; TestAbr, Test12Patr, ApcEsdr, ApcSed; AscIs 3:13; Philo, Leg. ad Gai. 7, Mos. 1, 96; Jos., Ant. 17, 164; SibOr 5, 388; Ar. [Milne 76, 43]; Just.).</p>\n<p class=\"entry-text\">① Imposição de sofrimento ou dor como castigo; punição, assim literalmente. <span class=\"greek\">κ</span>. <span class=\"greek\">ὑπομένειν</span>, sofrer punição, Ox 840, 6; <span class=\"greek\">δειναὶ</span> <span class=\"greek\">κ</span>., castigos terríveis (4 Macc 8:9), MPol 2:4; <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐπίμονος</span> <span class=\"greek\">κ</span>., tortura prolongada, na mesma passagem. Sobre o martírio de Jesus (Orig., C. Cels. 1, 48, 95; 8, 43, 12), PtK 4 p. 15, 34. Sentir o cheiro que se eleva dos sacrifícios dos politeístas é ironicamente descrito como punição, dano (veja <span class=\"greek\">κολάζω</span>), Dg 2:9.</p>\n<p class=\"entry-text\">② Retribuição transcendente; punição (ApcSed 4:1 <span class=\"greek\">κόλασις</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πῦρ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">παίδευσίς</span> <span class=\"greek\">σου</span>, tua disciplina é punição e fogo.—Diod S 3, 61, 5; 16, 61, 1; Epict. 3, 11, 1; Dio Chrys. 80 [30], 12; 2 Macc 4:38 e outras passagens na LXX; Philo, Spec. Leg. 1, 55; 2, 196; Jos., Ant. 1, 60 e outras passagens; Just.; Did., Gen., 115, 28; 158, 10), ApcPt 17:32; com <span class=\"greek\">αἰκισμός</span>, 1 Cl 11:1. Sobre a punição eterna (com <span class=\"greek\">θάνατος</span>), Dg 9:2 (Diod S 8, 15, 1 <span class=\"greek\">κ</span>. <span class=\"greek\">ἀθάνατος</span>, punição imortal). Do inferno: <span class=\"greek\">τόπος</span> <span class=\"greek\">κολάσεως</span>, lugar de punição, ApcPt 6:21 (Simplicius em Epict. p. 13, 1 <span class=\"greek\">εἰς</span> <span class=\"greek\">ἐκεῖνον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">κολάσεως</span> <span class=\"greek\">δεόμεναι</span> <span class=\"greek\">ψυχαὶ</span> <span class=\"greek\">καταπέμπονται</span>, para aquele lugar são enviadas as almas que necessitam de punição); <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐκείνῃ</span>, naquela punição, 10:25; na mesma passagem, <span class=\"greek\">ἐφορῶσαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐκείνων</span>, contemplando a punição deles (compare ApcEsdr 5:10 p. 30, 2 Tdf. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">κ</span>.). <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κ</span>., da punição, ApcPt Rainer (compare <span class=\"greek\">ἐκ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κ</span>., ApcSed 8:12a; <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κ</span>., 12b, e TestAbr B 11 p. 116, 10 [Stone p. 80]). <span class=\"greek\">ἀπέρχεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">αἰώνιον</span>, partir para a punição eterna, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:46</a> (<span class=\"greek\">οἱ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἄξιοι</span> <span class=\"greek\">ἀπελεύσονται</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">αὐτήν</span>, aqueles que merecem punição irão para ela, Iren. 2, 33, 5 [Harv. I 380, 8]; <span class=\"greek\">κ</span>. <span class=\"greek\">αἰώνιον</span> como em TestAbr A 11 p. 90, 7f [Stone p. 28]; TestReub 5:5; TestGad 7:5; Just., A I, 8, 4; D. 117, 3; Celsus 8, 48; no plural em Theoph. Ant. 1, 14 [p. 90, 13]). <span class=\"greek\">ῥύεσθαι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">αἰωνίου</span> <span class=\"greek\">κ</span>., livrar da punição eterna, 2 Cl 6:7. <span class=\"greek\">τὴν</span> <span class=\"greek\">αἰώνιον</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐξαγοράζεσθαι</span>, comprar a própria liberdade da punição eterna, MPol 2:3, variante de leitura. <span class=\"greek\">κακαὶ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">διαβόλου</span>, as más punições do diabo, IRo 5:3. <span class=\"greek\">κ</span>. <span class=\"greek\">τινος</span>, punição por alguma coisa (Ezk 14:3, 4, 7; 18:30; Philo, Fuga 65 <span class=\"greek\">ἁμαρτημάτων</span> <span class=\"greek\">κ</span>.), <span class=\"greek\">ἔχειν</span> <span class=\"greek\">κόλασίν</span> <span class=\"greek\">τινα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πονηρίας</span> <span class=\"greek\">αὐτοῦ</span>, sofrer certa punição por sua maldade, Hs 9, 18, 1. <span class=\"greek\">ἀναπαύστως</span> <span class=\"greek\">ἕξουσιν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κ</span>., sofrerão punição incessante, ApcPt Bodl. 9–12. <span class=\"greek\">ὁ</span> <span class=\"greek\">φόβος</span> <span class=\"greek\">κόλασιν</span> <span class=\"greek\">ἔχει</span>, o medo está relacionado com a punição, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:18</a> (compare Philo, In Flacc. 96 <span class=\"greek\">φόβος</span> <span class=\"greek\">κολάσεως</span>).—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0206-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κολασσαεύς</h1><div class=\"entry-meta\"><span>substantivo masculino; variante gráfica e remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κολασσαεύς</span> (<span class=\"greek\">Κολοσσαεύς</span>, <span class=\"greek\">Κολοσαεύς</span>, <span class=\"greek\">Κολασαεύς</span>), <span class=\"greek\">έως</span>, <span class=\"greek\">ὁ</span>: colossense (veja <span class=\"greek\">Κολοσσαί</span>). Somente como variante de leitura (mas já em P46) no título da Epístola aos Colossenses.—B-D-F §42, 3; Mlt-H. 73; 350.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0206-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κολασσαί</h1><div class=\"entry-meta\"><span>nome próprio geográfico; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κολασσαί</span>: veja <span class=\"greek\">Κολοσσαί</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0206-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κολαφίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κολαφίζω</span>: 1º aoristo <span class=\"greek\">ἐκολάφισα</span> (palavra não ática, do vernáculo, derivada de <span class=\"greek\">κόλαφις</span>; veja Lobeck, Phryn. 175 [compare Terence, Adelphi. 245 colaphis tuber est totum caput = (minha) cabeça está cheia de inchaços por causa de (seus) golpes]; Mlt-H. 364; 407. Encontrada quase exclusivamente em literatura cristã; também em Paus. Attic. <span class=\"greek\">κ</span>, 38; carta greco-romana: Sb 6263, 23 [época romana]; TestJos 7:5, variante de leitura.—Hesychius: <span class=\"greek\">κολαφιζόμενος</span>· <span class=\"greek\">ῥαπιζόμενος</span>, aquele que recebe pancadas; Etym. Mag. 525, 4).</p>\n<p class=\"entry-text\">① Golpear com força, especialmente com a mão; esmurrar, espancar, dar bofetadas; com <span class=\"greek\">τινά</span>, alguém. Literalmente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.67\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:67</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.65\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:65</a> (KSchmidt, MGoguel Festschr. ’50, 218–27); MPol 2:4 (variante de leitura). Sobre maus-tratos em geral: somos tratados brutalmente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:11</a>. <span class=\"greek\">εἰ</span> <span class=\"greek\">κολαφιζόμενοι</span> <span class=\"greek\">ὑπομενεῖτε</span>, se suportais ser espancados, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:20</a> (variante <span class=\"greek\">κολαζόμενοι</span>).</p>\n<p class=\"entry-text\">② Causar padecimento físico, atormentar; extensão figurada do sentido 1, quanto aos ataques dolorosos de uma enfermidade, descritos como espancamento físico por um mensageiro de Satanás, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:7</a>. Os dados disponíveis para um diagnóstico científico são escassos, e não surpreende que se tenham defendido várias interpretações caracterizadas por numerosas conjecturas: ⓐ epilepsia: MKrenkel, Beiträge 1890, 47ff; Schmiedel e Bousset ad loc.; WWrede, Paulus2 1907, 17; HFischer (médico), D. Krankheit d. Ap. Pls. 1911; veja também WWeber (psiquiatra), TLZ 37, 1912, 623; FConybeare em WBundy, The Psychic Health of Jesus 1922, 226f; ASchweitzer, D. Mystik des Ap. Pls. 1930, 152; JKlausner, From Jesus to Paul ’43, 325–30. ⓑ histeria: ELombard, Les extases et les souffrances de l’apôtre Paul: RTP 36, 1903, 450–500; Windisch ad loc.; FFenner, D. Krankheit im NT 1930, 30–40. ⓒ depressão periódica: veja KBonhoeffer (médico) em Ltzm., Hdb. ad loc. ⓓ cefaleias e doença ocular grave: Seeligmüller (médico), War Paulus Epileptiker? 1910; compare WWeber, TLZ 36, 1911, 235; Uhle-Wettler, Evang. Kirchenztg. 87, 1913, 130ff; 145ff. ⓔ malária: Ramsay, Church2 63ff; Sickenberger, comentário ad loc. ⓕ lepra: EPreuschen, ZNW 2, 1901, 193f; REisler, <span class=\"greek\">Ιησους</span> <span class=\"greek\">βασιλευς</span> II 1930, 426ff; 794. ⓖ impedimento na fala (gagueira): WClarke, ET 39, 1928, 458–60. Veja também <span class=\"greek\">σκόλοψ</span>.—Para interpretações (anteriormente preferidas por muitos) que apontam para tentações interiores provocadas por adversários, remorsos ou estados de aflição, veja GHeinrici em KEK8 1900 ad loc.; PMenoud, em JdeZwaan Festschr. ’53, entende tratar-se das angústias da vida missionária.—B. 553 s.v. <span class=\"greek\">κόλαφος</span>. DELG s.v. <span class=\"greek\">κόλαφος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0206-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κολλάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κολλάω</span>: aoristo <span class=\"greek\">ἐκόλλησα</span>, LXX; perfeito <span class=\"greek\">κεκόλληκα</span>, Job 38:38. Na passiva: 1º futuro <span class=\"greek\">κολληθήσομαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:5</a>; 1º aoristo <span class=\"greek\">ἐκολλήθην</span>; perfeito passivo <span class=\"greek\">κεκόλλημαι</span>, LXX (<span class=\"greek\">κόλλα</span>, ‘cola’; Aeschyl. e outros; Pla., Diod S, Plut., inscrições, papiros, LXX; TestAbr A 20 p. 103, 18 [Stone p. 54]; Test12Patr; AscIs 97; EpArist 97; Philo); em geral, ‘unir’.</p>\n<p class=\"entry-text\">① Unir estreitamente, ligar firmemente, juntar; com <span class=\"greek\">τινά</span> <span class=\"greek\">τινι</span>, alguém a alguém; extensão figurada do significado literal ‘colar’ ou ‘unir’ substâncias, na ativa: <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀγάπη</span> <span class=\"greek\">κολλᾷ</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, o amor nos une a Deus, 1 Cl 49:5. <span class=\"greek\">ἡ</span> <span class=\"greek\">νουθέτησις</span> … <span class=\"greek\">κολλᾷ</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θελήματι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, a admoestação nos une à vontade de Deus, 56:2.</p>\n<p class=\"entry-text\">② Estar estreitamente associado, apegar-se, aderir, unir-se; na passiva, mais frequentemente com significado ativo.</p>\n<p class=\"entry-text\">ⓐ Aderir (estreitamente) a algo. <span class=\"greek\">α</span>. Literalmente, com <span class=\"greek\">τινί</span> (Job 29:10), sobre pedras, <span class=\"greek\">ἐκολλῶντο</span> <span class=\"greek\">ἀλλήλοις</span>, estavam unidas umas às outras, Hv 3, 2, 6. Da poeira: <span class=\"greek\">τὸν</span> <span class=\"greek\">κονιορτὸν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κολληθέντα</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πόλεως</span> <span class=\"greek\">ὑμῶν</span>, a poeira de vossa cidade que ficou aderida a nós, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:11</a>. <span class=\"greek\">β</span>. Figuradamente, aderir = entrar em contato estreito com (compare Ps 21:16; 43:26 <span class=\"greek\">ἐκολλήθη</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">γῆν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">γαστὴρ</span> <span class=\"greek\">ἡμῶν</span>, nosso ventre aderiu à terra. A ativa = ‘pôr em contato’, PGM 5, 457 <span class=\"greek\">κολλήσας</span> <span class=\"greek\">τ</span>. <span class=\"greek\">λίθον</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὠτίῳ</span>, tendo aproximado a pedra da orelha): <span class=\"greek\">ἐκολλήθησαν</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">ἁμαρτίαι</span> <span class=\"greek\">ἄχρι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρανοῦ</span>, os pecados atingiram o céu = chegaram até o céu (duas expressões condensadas), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:5</a>. <span class=\"greek\">γ</span>. Figuradamente, sobre o Espírito estreitamente unido à carne, 2 Cl 14:5.</p>\n<p class=\"entry-text\">ⓑ Unir-se a alguém, juntar-se, apegar-se, associar-se. <span class=\"greek\">α</span>. Referente a pessoa, com dativo de coisa: <span class=\"greek\">κολλήθητι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἅρματι</span> <span class=\"greek\">τούτῳ</span>, junta-te a este carro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:29</a> (uma tradução como ‘fica colado a este carro’ sugere a imagem).—Com dativo de pessoa (muito raramente substituído por construção preposicional [AscIs 3:1 <span class=\"greek\">πρὸς</span> <span class=\"greek\">αὐτόν</span>, mas <span class=\"greek\">τῷ</span> <span class=\"greek\">Μανασσῇ</span>; compare Tob 6:19 <span class=\"greek\">εἰ</span> <span class=\"greek\">αὐτήν</span> S, <span class=\"greek\">αὐτῇ</span> BA]), 1 Cl 30:3; compare 46:1. <span class=\"greek\">τοῖς</span> <span class=\"greek\">εἰρηνεύουσι</span>, aos pacificadores, 15:1. <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἁγίοις</span>, aos santos, 46:2 (citação de origem desconhecida); Hv 3, 6, 2; Hs 8, 8, 1. <span class=\"greek\">τοῖς</span> <span class=\"greek\">δούλοις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, aos servos de Deus, 9, 20, 2; 9, 26, 3. <span class=\"greek\">τοῖς</span> <span class=\"greek\">δικαίοις</span>, aos justos, 8, 9, 1. <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀθῴοις</span> <span class=\"greek\">κ</span>. <span class=\"greek\">δικαίοις</span>, aos inocentes e justos, 1 Cl 46:4. <span class=\"greek\">τοῖς</span> <span class=\"greek\">διψύχοις</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κενοῖς</span>, aos vacilantes e insensatos, Hm 11:13. <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀκαθάρτοις</span>, aos impuros, B 10:8; compare 10:3ff. Também com <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span> (compare Ruth 2:8), 10:11; 19:2, 6; D 3:9. <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span>, unir-se ao Senhor (compare 4 Km 18:6; Sir 2:3; sobre este versículo e 6:16 abaixo, veja SPorter, ETL 67, ’91, 104f: conotação econômica; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:15</a> abaixo), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:17</a>; Hm 10, 1, 6. <span class=\"greek\">τῇ</span> <span class=\"greek\">γυναικὶ</span> <span class=\"greek\">αὐτοῦ</span>, unir-se à própria esposa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:5</a> (compare Vi. Aesopi G 30 P. p. 46, 14, em que uma mulher diz a Esopo: <span class=\"greek\">μή</span> <span class=\"greek\">μοι</span> <span class=\"greek\">κολλῶ</span>, não te aproximes tanto de mim; 1 Esdr 4:20; Philo, Leg. All. 2, 50). <span class=\"greek\">τῇ</span> <span class=\"greek\">πόρνῃ</span>, unir-se a uma prostituta, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:16</a> (compare Sir 19:2). Associar-se intimamente, juntar-se, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:13</a>; 9:26; 10:28 (CBurchard, ZNW 61, ’70, 159f). Tornar-se seguidor ou discípulo de alguém (compare 2 Km 20:2; 1 Macc 3:2; 6:21), 17:34. Empregar-se a serviço de alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:15</a> (JHarrill, JBL 115, ’96, 714–17, ‘ficou vinculado por contrato de serviço’). Ter relações com: espíritos mentirosos, Hm 11:4. <span class=\"greek\">β</span>. De coisas impessoais: da ira, <span class=\"greek\">ὅταν</span> <span class=\"greek\">κολληθῇ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀνθρώπῳ</span>, quando se apega a uma pessoa, Hm 10, 2, 3. Também da punição, Hs 6, 5, 3.</p>\n<p class=\"entry-text\">ⓒ Com dativo de coisa, apegar-se, estabelecer relação estreita com (Ps 118:31; TestIss 6:1, Dan 6:10 <span class=\"greek\">τ</span>. <span class=\"greek\">δικαιοσύνῃ</span>, Gad 5:2): <span class=\"greek\">ταῖς</span> <span class=\"greek\">δωρεαῖς</span>, apegar-se aos dons, 1 Cl 19:2. <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀγαθῷ</span>, dedicar-se ao que é bom, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:9</a>; B 20:2; D 5:2 (compare TestAsh 3:1 <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀγαθότητι</span>). <span class=\"greek\">τῇ</span> <span class=\"greek\">εὐλογίᾳ</span>, apegar-se à bênção, 1 Cl 31:1. <span class=\"greek\">κρίσει</span> <span class=\"greek\">δικαίᾳ</span>, ao juízo justo, B 20:2.—DELG s.v. <span class=\"greek\">κόλλα</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0206-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κολλούριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κολλούριον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (esta é a grafia tardia, atestada em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:18</a> pelos manuscritos A P e outros; Philumen. p. 9, 16; PHolm 1, 16; PFlor 177, 20 [257 d.C.]; PGM 4, 1316; 2691; 2893. Por outro lado, certos manuscritos e editores apresentam <span class=\"greek\">κολλύριον</span>, como fazem Epict. 2, 21, 20; 3, 21, 21; Galen: CMG V 4, 2 p. 192, 30; Philumen. p. 33, 18; 22; Aëtius com muita frequência; SIG 1173, 16 [138 d.C.]; POxy 1088, 1 e 42 [I d.C.]; PGM 4, 2682; LXX [Thackeray 92].—Veja B-D-F §42, 4; Mlt-H. 78f; Crönert 130; KDieterich, Untersuchungen z. griech. Sprache 1898, 23): preparado medicinal aplicado aos olhos, colírio, unguento oftálmico (assim Epict., SIG, PFlor, nas passagens citadas; empréstimo no hebraico rabínico; diminutivo de <span class=\"greek\">κολλύρα</span>, ‘rolo’ ou ‘pão pequeno’, talvez devido ao formato do preparado; Mussies 25), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:18</a>.—Veja Wetstein para paralelos greco-romanos; FBayer, RAC 7, ’44, 973ff; HNielsen, Ancient Ophthalmological Agents, 1974; CHemer em New Docs 3, 56f; do mesmo autor, The Letters to the Seven Churches of Asia Minor in Their Local Setting ’89 (’86), 196–99; Kl. Pauly III 272; RJackson, Eye Medicine in the Rom. Empire: ANRW II Principat 37/3, ’96, 2228–51, especialmente 2238–43.—DELG s.v. <span class=\"greek\">κολλύρα</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0206-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κολλυβιστής, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κολλυβιστής</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">κόλλυβος</span>, ‘moeda pequena’; Lysias em Pollux 7, 33; 170; Menand., Fgm. 861 Kö. [em Phryn. 440 Lob.; mas os aticistas rejeitam a palavra no mesmo lugar]; PPetr III, 59a I, 7 [III a.C.]): cambista, trocador de dinheiro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:45</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:15</a>.—DELG s.v. <span class=\"greek\">κόλλυβος</span>. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0206-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κολλύριον</h1><div class=\"entry-meta\"><span>remissão lexical</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κολλύριον</span>: veja <span class=\"greek\">κολλούριον</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0206-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κολοβός, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κολοβός</span>, <span class=\"greek\">όν</span> (veja o verbete seguinte; X. e outros; PGen 23, 5 [70 d.C.]; PPetr III, 19g, 2; POxy 43 verso V, 9; Aq. e Sym. em Is 37:27): geralmente, de algo privado de uma saliência (<span class=\"greek\">κόλος</span>): de bois ou cabras sem chifres, daí ‘atrofiado’.</p>\n<p class=\"entry-text\">① Relativo ao que apresenta alguma deficiência; mutilado, na imagem das pedras talhadas: com alguma parte quebrada (oposto a <span class=\"greek\">ὁλοτελής</span>; compare as expressões ‘não corresponder à medida’ ou ‘ficar aquém’), Hv 3, 6, 4; Hs 9, 6, 4; 9, 8, 4; 9, 26, 7. <span class=\"greek\">κ</span>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span>, prejudicado na fé, 9, 26, 8.</p>\n<p class=\"entry-text\">② Relativo ao que não é alto; baixo, atarracado (Peripl. Eryth. c. 65; Galen, De Usu Part. I p. 58, 19 Helmr.; Procopius de Cesareia, Anecdota 8, 12 [oposto a <span class=\"greek\">μακρός</span>]; 10, 11): <span class=\"greek\">ἄνθρωπος</span> (oposto a <span class=\"greek\">μακρός</span>), Gospel of Eve: Kl. T. 83, p. 18.—DELG s.v. <span class=\"greek\">κόλος</span>. M-M s.v. <span class=\"greek\">κολοβόω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0206-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κολοβόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κολοβόω</span>: 1º aoristo <span class=\"greek\">ἐκολόβωσα</span>. Passiva: 1º futuro <span class=\"greek\">κολοβωθήσομαι</span>; 1º aoristo <span class=\"greek\">ἐκολοβώθην</span>; particípio perfeito <span class=\"greek\">κεκολοβωμένος</span> (veja o verbete precedente; Aristot., HA 1, 1, 487b, 24; Diod S 1, 78, 5; 2 Km 4:12 ‘cortar, encurtar’; GrBar 9:7; Ar.13, 2): ‘mutilar, abreviar’ (assim Polyb. 1, 80, 13; Epict. 2, 10, 20).</p>\n<p class=\"entry-text\">① Fazer com que algo não tenha seu comprimento pleno; encurtar, literalmente, de pedras: <span class=\"greek\">κεκολοβωμένοι</span>, encurtadas, Hv 3, 2, 8; 3, 6, 4 (veja NBrox, Der Hirt des Hermas ’91, 135). <span class=\"greek\">ὅλως</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ἐκολοβώθη</span>, nada nelas foi encurtado de modo algum, Hs 9, 8, 5.</p>\n<p class=\"entry-text\">② Reduzir a duração de algo; abreviar, extensão figurada do sentido 1: os últimos dias, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:22ab</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:20ab</a> (compare GrBar 9:7 <span class=\"greek\">θεὸς</span> … <span class=\"greek\">ἐκολόβωσεν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">αὐτῆς</span> [isto é, <span class=\"greek\">τῆς</span> <span class=\"greek\">σελήνης</span>]).—DELG s.v. <span class=\"greek\">κόλος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0206-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κολοσσαεύς, έως</h1><div class=\"entry-meta\"><span>substantivo masculino; gentílico</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κολοσσαεύς</span>, <span class=\"greek\">έως</span> (Suda sobre <span class=\"greek\">Ῥόδος</span>: IV p. 297, 15): colossense; substantivado, <span class=\"greek\">ὁ</span> <span class=\"greek\">Κ</span>., o colossense, Col, inscrição inicial da epístola.—Alguns manuscritos e editores escrevem <span class=\"greek\">Κολασς</span>. (veja o verbete correspondente), forma também encontrada na Suda, na passagem citada, como variante de leitura (Strabo 12, 8, 16 emprega a forma <span class=\"greek\">Κολοσσηνός</span>).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0206-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κολοσσαί, ῶν, αἱ</h1><div class=\"entry-meta\"><span>nome próprio geográfico feminino plural</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κολοσσαί</span>, <span class=\"greek\">ῶν</span>, <span class=\"greek\">αἱ</span>: Colossos, outrora uma cidade próspera (Hdt. 7, 30; X., An. 1, 2, 6), depois de menor importância (Strabo 12, 8, 13 <span class=\"greek\">πόλισμα</span>, pequena cidade), na Frígia, Ásia Menor. A congregação local provavelmente foi fundada por Epafras (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:7</a>), que era de Colossos (4:12). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:2</a>; Phlm subscrição, variante de leitura.—Lghtf., Col and Phlm p. 1ff; Ramsay, Church 465ff, Phrygia I/1, 208ff; VSchultze, Altchr. Städte u. Landschaften II 1, 1922, 445ff; Zahn, Einl. I3 318, que, assim como Lghtf. 16, 4, examina as formas variantes do nome (<span class=\"greek\">Κολασσαί</span>, <span class=\"greek\">Κολασαί</span>). BHHW II 975f.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0206-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κόλπος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κόλπος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (desde Hom.; inscrições, papiros, LXX; TestSol 2:3 W; TestAbr; TestJob 10:4; JosAs cap. 11 códice A [p. 52, 11 Bat.]; ApcSed 14:6; Philo, Joseph.): diversos sentidos no uso literário geral, frequentemente sugerindo curvatura e o espaço côncavo assim formado, como no peito de uma pessoa, nas dobras de uma vestimenta ou numa baía do mar; nossa literatura não contém aplicação do termo a partes anatômicas exclusivamente femininas.</p>\n<p class=\"entry-text\">① Seio, peito, tórax. <span class=\"greek\">ἀνακεῖσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κόλπῳ</span> <span class=\"greek\">τινός</span>, reclinar-se (à refeição) com a cabeça sobre o peito de alguém (posição determinada pelo costume antigo de banquetear: veja <span class=\"greek\">ἀνάκειμαι</span> 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:23</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">κόλποις</span> <span class=\"greek\">αὐτοῦ</span> (=<span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἀβραάμ</span>; neste caso deve-se suprir <span class=\"greek\">ἀνακείμενον</span>), reclinado no seio de Abraão (no lugar de honra do banquete no mundo vindouro. Sobre o plural, veja B-D-F §141, 5; Rob. 408; Theocr. 2, 120 e abaixo; Plut., Cato Min. 775 [33, 4]; compare também Sb 2034, 11 <span class=\"greek\">ἐν</span> <span class=\"greek\">κόλποις</span> <span class=\"greek\">Ἀβρὰμ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">Ἰσὰκ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">Ἰακώβ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:23</a>. <span class=\"greek\">ἀπενεχθῆναι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">Ἀβραάμ</span>, ser levado ao seio de Abraão, v. 22 (New Docs 3, 106f). Para <span class=\"greek\">κόλποι</span> é possível também o sentido ‘colo’ (Ael. Aristid. 13 p. 163 D.: <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">κόλπων</span> <span class=\"greek\">τ</span>. <span class=\"greek\">γῆς</span>; Diog. L. 3, 44; Meleager, Anth. Pal. 5, 165 <span class=\"greek\">ἐν</span> <span class=\"greek\">κόλποισιν</span> <span class=\"greek\">ἐκείνης</span> = reclinado no colo dela; Anonymous Vita Pla. ed. Westerm. 1850 p. 5, 31 <span class=\"greek\">ἐντὸς</span> <span class=\"greek\">κόλπων</span> em lugar de 2, 44 <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">γόνασιν</span>); no singular, nesse sentido: <span class=\"greek\">ἦλθεν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">μητρός</span>, veio ao colo da mãe, GJs 6:1 (Epict. 2, 5, 16; 4, 7, 24; Vi. Aesopi G 82; 137 P.; Ps.-Clem., Hom. 8, 12 [compare Piers Plowman, versão C 9, 283 ‘in Abrahammes lap’; PHaupt, AJP 42, 1921, 162–67; ESchwyzer, Der Götter Knie—Abrahams Schoss: JWackernagel Festschr. 1923, 283–93; MMieses, Im Schosse Abrahams: OLZ 34, ’31, 1018–21; contra este, BHeller, ibid. 36, ’33, 146–49.—Fontes rabínicas em RMeyer, TW III 825]). <span class=\"greek\">ἐὰν</span> <span class=\"greek\">ἦτε</span> <span class=\"greek\">συνηγμένοι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μου</span>, se estiverdes reunidos em meu seio, 2 Cl 4:5 (dito de Jesus; compare Judaicon 68, 41f, duas vezes). Além disso, independentemente da ideia de comer juntos no mesmo divã, ‘estar no seio de alguém’ denota a associação mais estreita (compare Plut., Pericl. 1, 1, Demosth. 31, 6, Cato Min. 33, 7 Ziegler, variante de leitura: Gabinius, um <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Πομπηί̈ου</span> <span class=\"greek\">κόλπων</span>; Longus, Past. 4, 36, 3; Num 11:12; Dt 13:7; 28:54, 56; 2 Km 12:3; 3 Km 17:19; Ruth 4:16): <span class=\"greek\">ὁ</span> <span class=\"greek\">ὢν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρός</span>, aquele que repousa no seio do Pai, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:18</a> (M-EBoismard, RB 59, ’52, 23–39; OHofius, ZNW 80, ’89, 163–71).</p>\n<p class=\"entry-text\">② Dobra de uma vestimenta, dobra formada quando o tecido cai do peito sobre o cinto (Hom. e outros; Jos., Ant. 2, 273). Desde tempos remotos (por exemplo, Od. 15, 468; Herodas 6, 102; Diod S 25, 16; Appian, Iber. 13 §49; Polyaenus 7, 48; 8, 64; Dio Chrys. 67 [17], 22; Ex 4:6f; Jos., Bell. 6, 195), essa dobra era usada como bolso. <span class=\"greek\">διδόναι</span> <span class=\"greek\">τι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τινός</span>, pôr alguma coisa na dobra da roupa de alguém (compare Polyb. 3, 33, 2; Ps 78:12; Is 65:6; Jer 39:18; TestJob 10:4 <span class=\"greek\">κόλπῳ</span> <span class=\"greek\">κενῷ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:38</a>.</p>\n<p class=\"entry-text\">③ Parte do mar que penetra no litoral, baía (Hom. e outros; OGI 441, 218; Philo, Op. M. 113; Jos., Ant. 3, 25), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:39</a>.—B. 39. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0206-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κολυμβάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κολυμβάω</span> (veja o verbete seguinte; Pla. e outros).</p>\n<p class=\"entry-text\">① Nadar subindo e descendo, literalmente, ‘mergulhar’, B 10:5.</p>\n<p class=\"entry-text\">② Nadar (Paradoxogr. Flor. 10; Palaeph. p. 36, 5; Babrius 165, 1; 3 C.; Is 25:11 Aq.; Jos., Ant. 20, 248): <span class=\"greek\">τοὺς</span> <span class=\"greek\">δυναμένους</span> <span class=\"greek\">κ</span>., aqueles que sabiam nadar, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.43\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:43</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0206-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κολυμβήθρα, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κολυμβήθρα</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (veja <span class=\"greek\">κολυμβάω</span>; Pla. e outros; Diod S 4, 78, 1; 11, 25, 4; Jos., Ant. 9, 239; 15, 54; POxy 147, 2; LXX): piscina, tanque (utilizado para banho: Ael. Aristid. 48, 21 K. = 24 p. 470 D.). Da piscina de Betzata (veja <span class=\"greek\">Βηθζαθά</span> e JJeremias, D. Wiederentdeckung von Bethesda ’49), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:2</a>, 3 (4), variante de leitura, 7; Siloé, 9:7, 11, variante de leitura (2 Esdr 13:15 S <span class=\"greek\">κολυμβήθρα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Σιλωάμ</span>).—DELG s.v. <span class=\"greek\">κόλυμβος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0206-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κολωνία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κολωνία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (empréstimo do latim colonia; encontrado também no hebraico rabínico. Exemplos em Hahn 271, índice de palavras latinas; edito de Cláudio em Jos., Ant. 19, 291): cidade ou povoação fora da Itália cujos habitantes desfrutavam de privilégios políticos especiais: colônia; de Filipos, na Macedônia, colonizada por Augusto (veja <span class=\"greek\">Φίλιπποι</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:12</a>.—M-M.</p></section></article>"};
